35	export async function listBoards(): Promise<BoardSummary[]> {
36	  await requireAdmin();
37	  let boards = await db.board.findMany({ orderBy: { createdAt: "asc" }, include: { _count: { select: { cards: true } } } });
38	  if (boards.length === 0) {
39	    await createBoardInternal("Nxeon");
40	    boards = await db.board.findMany({ orderBy: { createdAt: "asc" }, include: { _count: { select: { cards: true } } } });
41	  }
42	  return boards.map((b) => ({ id: b.id, name: b.name, cardCount: b._count.cards }));
43	}
