33	export function BoardClient({ boards, board }: { boards: BoardSummary[]; board: BoardData | null }) {
34	  const router = useRouter();
35	  const [openCard, setOpenCard] = useState<string | null>(null);
36	  const [drag, setDrag] = useState<string | null>(null);
37	  // Local column state for optimistic moves.
38	  const [cols, setCols] = useState<ColumnData[]>(board?.columns ?? []);
39	  useEffect(() => setCols(board?.columns ?? []), [board?.id, board?.columns]);
