41	  async function newBoard() {
42	    const name = prompt("New board name (e.g. Soul Pilates)");
43	    if (!name?.trim()) return;
44	    const res = await createBoard(name.trim());
45	    if (res.id) router.push(`/admin/board?b=${res.id}`);
46	  }
