48	  async function onDrop(colId: string, index: number) {
49	    if (!drag) return;
50	    const cardId = drag;
51	    setDrag(null);
52	    // Optimistic: remove from old col, insert into new.
53	    setCols((prev) => {
54	      let moved: CardSummary | undefined;
55	      const stripped = prev.map((c) => ({ ...c, cards: c.cards.filter((cd) => (cd.id === cardId ? ((moved = cd), false) : true)) }));
56	      if (!moved) return prev;
57	      return stripped.map((c) => (c.id === colId ? { ...c, cards: [...c.cards.slice(0, index), moved!, ...c.cards.slice(index)] } : c));
58	    });
59	    await moveCard(cardId, colId, index);
60	  }
61	
62	  return (
63	    // Fill the viewport so the board occupies the page instead of floating in a
64	    // sea of dead space. Height is viewport-relative (works regardless of the
65	    // admin shell's own layout); the columns row below takes the remaining space.
