#!/bin/bash
# One-time GitHub setup using the server's deploy key.
#
# Prereq: add /root/.ssh/nxeon_deploy.pub to your repo as a deploy key
#         (repo Settings -> Deploy keys -> Add) WITH "Allow write access".
#
# Usage (SSH remote — required for deploy keys):
#   ./scripts/setup-github.sh git@github.com:<user>/nxeon.git
set -euo pipefail

REMOTE="${1:-}"
if [ -z "$REMOTE" ]; then
  echo "Usage: $0 git@github.com:<user>/<repo>.git" >&2
  exit 1
fi
case "$REMOTE" in
  https://*)
    echo "Use the SSH remote (git@github.com:user/repo.git) — deploy keys don't work over HTTPS." >&2
    exit 1 ;;
esac

echo "==> Verifying deploy key can reach GitHub"
if ssh -o BatchMode=yes -o ConnectTimeout=10 -T git@github.com 2>&1 | grep -qi "successfully authenticated"; then
  echo "    deploy key authenticated OK"
else
  echo "    GitHub has not accepted the key. Add /root/.ssh/nxeon_deploy.pub to the repo"
  echo "    as a deploy key with write access, then re-run this script." >&2
  exit 1
fi

cd /opt/nxeon
git remote remove origin 2>/dev/null || true
git remote add origin "$REMOTE"
echo "==> Pushing main to $REMOTE"
git push -u origin main
echo "==> Done. Every future commit now auto-pushes via .git/hooks/post-commit."
