 *
 * Meant to be called by the nightly scan, one invocation per finding:
 *
 *   npx tsx scripts/write-improvement.ts \
 *     --category bug --severity high \
 *     --title "Race in provisioning worker" \
 *     --summary "Two jobs can grab the same IP under load." \
 *     [--detail "..."] [--batchId 2026-07-24] [--source nightly-scan] \
